package de.klarlernen.app;

import org.json.*;
import java.util.*;

/** Local-only learning rules. Data has no cloud account or paid service. */
public final class LearningEngine {
    public final JSONObject catalog;public JSONObject state;
    public LearningEngine(JSONObject catalog,String saved)throws JSONException{this.catalog=catalog;try{JSONObject s=new JSONObject(saved==null?"":saved);validate(s);state=s;}catch(Exception e){state=fresh();}}
    public JSONObject fresh()throws JSONException{JSONObject s=new JSONObject();s.put("schema",1);JSONObject p=new JSONObject();p.put("name","").put("grade",10).put("school","Gesamtschule").put("language","de").put("minutes",15).put("date","").put("dark",false).put("onboarded",false);JSONArray chosen=new JSONArray();for(int i=0;i<units().length();i++)chosen.put(units().getJSONObject(i).getString("id"));p.put("subjects",chosen);return s.put("profile",p).put("attempts",new JSONArray()).put("sessions",new JSONArray()).put("reviews",new JSONArray()).put("levels",new JSONObject()).put("lessonPositions",new JSONObject()).put("active",JSONObject.NULL);}
    public JSONArray units()throws JSONException{return catalog.getJSONArray("units");}
    public JSONObject unit(String id)throws JSONException{for(int i=0;i<units().length();i++){JSONObject u=units().getJSONObject(i);if(u.getString("id").equals(id))return u;}throw new JSONException("Unknown unit");}
    public JSONObject question(String unit,String id)throws JSONException{JSONArray qs=unit(unit).getJSONArray("items");for(int i=0;i<qs.length();i++)if(qs.getJSONObject(i).getString("id").equals(id))return qs.getJSONObject(i);throw new JSONException("Unknown question");}
    public JSONObject profile()throws JSONException{return state.getJSONObject("profile");}public JSONObject active(){return state.optJSONObject("active");}
    public void validate(JSONObject s)throws JSONException{if(s.getInt("schema")!=1)throw new JSONException("Schema");JSONObject p=s.getJSONObject("profile");JSONArray selected=p.getJSONArray("subjects");if(selected.length()==0)throw new JSONException("No subjects");for(int i=0;i<selected.length();i++)unit(selected.getString(i));if(!Arrays.asList(10,15,20).contains(p.getInt("minutes"))||!Arrays.asList("de","tr").contains(p.getString("language")))throw new JSONException("Profile");JSONArray attempts=s.getJSONArray("attempts");if(attempts.length()>50000)throw new JSONException("Too large");for(int i=0;i<attempts.length();i++){JSONObject a=attempts.getJSONObject(i);question(a.getString("unit"),a.getString("questionId"));if(!Arrays.asList("correct","incorrect").contains(a.getString("status")))throw new JSONException("Status");a.getLong("time");a.getString("answer");}JSONArray rs=s.getJSONArray("reviews");for(int i=0;i<rs.length();i++){JSONObject r=rs.getJSONObject(i);question(r.getString("unit"),r.getString("questionId"));r.getLong("due");if(r.getInt("stage")<0||r.getInt("stage")>2)throw new JSONException("Stage");}s.getJSONArray("sessions");JSONObject a=s.optJSONObject("active");if(a!=null){JSONArray queue=a.getJSONArray("queue");if(a.getInt("index")<0||a.getInt("index")>=queue.length())throw new JSONException("Index");for(int i=0;i<queue.length();i++){JSONObject q=queue.getJSONObject(i);question(q.getString("unit"),q.getString("questionId"));}a.getJSONObject("draft");a.getJSONArray("results");if(!Arrays.asList("practice","review","exam","diagnostic").contains(a.getString("mode")))throw new JSONException("Mode");}}
    public List<JSONObject> plan()throws JSONException{List<JSONObject> out=new ArrayList<>();JSONArray selected=profile().getJSONArray("subjects"),as=state.getJSONArray("attempts"),rs=state.getJSONArray("reviews");for(int i=0;i<selected.length();i++){String id=selected.getString(i);int wrong=0,due=0;long last=0;int seen=0;for(int j=as.length()-1;j>=0&&seen<10;j--){JSONObject a=as.getJSONObject(j);if(a.getString("unit").equals(id)){seen++;last=Math.max(last,a.getLong("time"));if(a.getString("status").equals("incorrect"))wrong++;}}for(int j=0;j<rs.length();j++){JSONObject r=rs.getJSONObject(j);if(r.getString("unit").equals(id)&&r.getLong("due")<=System.currentTimeMillis())due++;}out.add(new JSONObject().put("unit",id).put("wrong",wrong).put("due",due).put("last",last).put("priority",due*10+wrong*2+(last==0?1:0)));}out.sort((a,b)->{int diff=Integer.compare(b.optInt("priority"),a.optInt("priority"));return diff==0?Long.compare(a.optLong("last"),b.optLong("last")):diff;});return out.subList(0,Math.min(out.size(),Math.max(1,profile().getInt("minutes")/5)));}
    JSONObject draft()throws JSONException{return new JSONObject().put("answer","").put("steps","").put("hints",0).put("solution",false).put("wrong",false).put("locked",false).put("lastSubmission","");}
    public void begin(String mode,String unitId,int count,boolean timed)throws JSONException{if(active()!=null)return;JSONArray queue=new JSONArray(),reviews=state.getJSONArray("reviews");List<JSONObject> rlist=new ArrayList<>();if(mode.equals("review")){for(int i=0;i<reviews.length();i++){JSONObject r=reviews.getJSONObject(i);if(unitId==null||r.getString("unit").equals(unitId))rlist.add(r);}rlist.sort(Comparator.comparingLong(r->r.optLong("due")));count=Math.min(count,rlist.size());if(count==0)throw new JSONException("No reviews");}List<JSONObject> plan=plan();for(int i=0;i<count;i++){JSONObject r=mode.equals("review")?rlist.get(i):null;String id=r!=null?r.getString("unit"):unitId!=null?unitId:plan.get(i%plan.size()).getString("unit");JSONArray qs=unit(id).getJSONArray("items");JSONObject source=r!=null?question(id,r.getString("questionId")):null;Set<String> recent=new HashSet<>();JSONArray attempts=state.getJSONArray("attempts");for(int j=Math.max(0,attempts.length()-8);j<attempts.length();j++)recent.add(attempts.getJSONObject(j).getString("questionId"));for(int j=0;j<queue.length();j++)recent.add(queue.getJSONObject(j).getString("questionId"));List<JSONObject> pool=new ArrayList<>(),fallback=new ArrayList<>();for(int j=0;j<qs.length();j++){JSONObject q=qs.getJSONObject(j);if(source!=null&&(q.getString("id").equals(source.getString("id"))||!q.getString("objective").equals(source.getString("objective"))))continue;fallback.add(q);if(!recent.contains(q.getString("id")))pool.add(q);}if(pool.isEmpty())pool=fallback;int level=state.getJSONObject("levels").optInt(id,1);pool.sort(Comparator.comparingInt(q->Math.abs(q.optInt("difficulty")-level)));JSONObject q=pool.get(mode.equals("exam")?i%pool.size():0);queue.put(new JSONObject().put("unit",id).put("questionId",q.getString("id")).put("reviewId",r==null?JSONObject.NULL:r.getString("id")));}state.put("active",new JSONObject().put("id",UUID.randomUUID().toString()).put("mode",mode).put("queue",queue).put("index",0).put("draft",draft()).put("results",new JSONArray()).put("started",System.currentTimeMillis()).put("timed",timed));}
    public JSONObject entry()throws JSONException{return active().getJSONArray("queue").getJSONObject(active().getInt("index"));}public JSONObject current()throws JSONException{JSONObject e=entry();return question(e.getString("unit"),e.getString("questionId"));}
    String norm(String s){return s.trim().toLowerCase(Locale.GERMAN).replaceAll("[.!?]+$","").replaceAll("\\s+"," ");}
    public JSONObject check(JSONObject q,String answer,String steps)throws JSONException{String type=q.getString("type");if(type.equals("math")){SafeMath.Result r=SafeMath.check(q.getString("expression"),answer,steps);return new JSONObject().put("status",r.status).put("code",r.code).put("line",r.line);}if(answer.trim().isEmpty())return new JSONObject().put("status","unsupported").put("code","empty");boolean correct=false;if(type.equals("numeric")){try{correct=Math.abs(SafeMath.answer(answer).value()-Double.parseDouble(q.getString("answer")))<=q.optDouble("tolerance",0.000001);}catch(Exception e){return new JSONObject().put("status","unsupported").put("code","numeric_format");}}else{JSONArray answers=q.optJSONArray("accepted");if(answers==null)correct=norm(answer).equals(norm(q.getString("answer")));else for(int i=0;i<answers.length();i++)if(norm(answer).equals(norm(answers.getString(i))))correct=true;}return new JSONObject().put("status",correct?"correct":"incorrect").put("code","content");}
    public void addReview(String unit,String question)throws JSONException{JSONArray rs=state.getJSONArray("reviews");for(int i=0;i<rs.length();i++){JSONObject r=rs.getJSONObject(i);if(r.getString("questionId").equals(question)){r.put("stage",0).put("due",System.currentTimeMillis()+86400000L);return;}}rs.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("unit",unit).put("questionId",question).put("stage",0).put("due",System.currentTimeMillis()+86400000L));}
    public JSONObject submit()throws JSONException{JSONObject a=active(),d=a.getJSONObject("draft"),q=current(),e=entry();if(d.getBoolean("locked"))return null;String answer=d.getString("answer"),steps=d.getString("steps"),signature=answer+"\u0000"+steps;if(signature.equals(d.getString("lastSubmission")))return null;JSONObject result=check(q,answer,steps);d.put("feedback",result);String status=result.getString("status");if(!status.equals("correct")&&!status.equals("incorrect"))return result;d.put("lastSubmission",signature);boolean helped=d.getInt("hints")>0||d.getBoolean("solution")||d.getBoolean("wrong");JSONObject r=new JSONObject().put("id",UUID.randomUUID().toString()).put("taskId",a.getString("id")+":"+a.getInt("index")).put("unit",e.getString("unit")).put("questionId",q.getString("id")).put("contentVersion",q.getString("contentVersion")).put("mode",a.getString("mode")).put("status",status).put("answer",answer).put("steps",steps).put("hints",d.getInt("hints")).put("help",helped).put("time",System.currentTimeMillis()).put("code",result.getString("code")).put("line",result.optInt("line"));state.getJSONArray("attempts").put(r);if(status.equals("incorrect")){d.put("wrong",true);addReview(e.getString("unit"),q.getString("id"));}if(status.equals("correct")||a.getString("mode").equals("exam")||a.getString("mode").equals("diagnostic")){d.put("locked",true);a.getJSONArray("results").put(r);if(a.getString("mode").equals("review")&&status.equals("correct")&&!e.isNull("reviewId")){JSONArray rs=state.getJSONArray("reviews"),remaining=new JSONArray();for(int i=0;i<rs.length();i++){JSONObject review=rs.getJSONObject(i);if(review.getString("id").equals(e.getString("reviewId"))){int stage=review.getInt("stage");if(!helped&&stage==2)continue;int next=helped?0:stage+1;review.put("stage",next).put("due",System.currentTimeMillis()+catalog.getJSONArray("reviewDays").getInt(next)*86400000L);}remaining.put(review);}state.put("reviews",remaining);}}adapt(e.getString("unit"));return result;}
    void adapt(String unit)throws JSONException{JSONArray all=state.getJSONArray("attempts");List<JSONObject> last=new ArrayList<>();for(int i=all.length()-1;i>=0&&last.size()<3;i--){JSONObject a=all.getJSONObject(i);if(a.getString("unit").equals(unit)&&a.getString("mode").equals("practice"))last.add(a);}JSONObject levels=state.getJSONObject("levels");int level=levels.optInt(unit,1);if(last.size()==3&&last.stream().allMatch(a->a.optString("status").equals("correct")&&!a.optBoolean("help")))levels.put(unit,Math.min(3,level+1));else if(last.size()>=2&&last.get(0).optString("status").equals("incorrect")&&last.get(1).optString("status").equals("incorrect"))levels.put(unit,Math.max(1,level-1));}
    public JSONObject next()throws JSONException{JSONObject a=active();if(a==null||!a.getJSONObject("draft").getBoolean("locked"))return null;int index=a.getInt("index");if(index+1<a.getJSONArray("queue").length()){a.put("index",index+1).put("draft",draft());return null;}JSONArray results=a.getJSONArray("results");int correct=0,independent=0,help=0;for(int i=0;i<results.length();i++){JSONObject r=results.getJSONObject(i);if(r.getString("status").equals("correct")){correct++;if(!r.getBoolean("help"))independent++;}if(r.getBoolean("help"))help++;}JSONObject summary=new JSONObject().put("id",a.getString("id")).put("mode",a.getString("mode")).put("started",a.getLong("started")).put("finished",System.currentTimeMillis()).put("total",a.getJSONArray("queue").length()).put("skipped",a.getJSONArray("queue").length()-results.length()).put("correct",correct).put("independent",independent).put("help",help).put("results",results);state.getJSONArray("sessions").put(summary);state.put("active",JSONObject.NULL);return summary;}
    public JSONObject skip()throws JSONException{JSONObject e=entry();addReview(e.getString("unit"),e.getString("questionId"));active().getJSONObject("draft").put("locked",true);return next();}
    public List<JSONObject> latest()throws JSONException{Map<String,JSONObject> map=new LinkedHashMap<>();JSONArray as=state.getJSONArray("attempts");for(int i=0;i<as.length();i++){JSONObject a=as.getJSONObject(i);if(!a.getString("mode").equals("diagnostic"))map.put(a.getString("taskId"),a);}return new ArrayList<>(map.values());}
}
